// ---------- explaining decisions as the checks that ran ----------

const STATE_CHECK = "State and audit log verify (MAC, signed head, key pin)";

/** Adapter checks in the order the code runs them (core/state.ts, core/access/policy.ts, core/adapter.ts). */
function adapterChecks(reply                         , reason               )          {
  if (reply.error === "integrity_failure") return [{ name: STATE_CHECK, pass: false }];
  const chain                     = [
    ["File exists", "unknown_asset"],
    ["Account not disabled", "disabled"],
    ["Identity not revoked", "revoked"],
    ["Identity owns the file", "not_owner"],
    ["Identity not quarantined", "quarantined"],
  ];
  const out          = [{ name: STATE_CHECK, pass: true }];
  for (const [name, code] of chain) {
    if (reason === code) return [...out, { name, pass: false }];
    out.push({ name, pass: true });
  }
  return out;
}

/** Cluster node checks in the order ClusterNode.authorize runs them. */
function nodeChecks(reason        )          {
  const chain                       = [
    ["Node holds a verified policy", ["no_policy"]],
    ["Device is enrolled", ["unknown_device"]],
    ["Device belongs to the user", ["device_owner_mismatch"]],
    ["Device not revoked", ["device_revoked"]],
    ["User not revoked", ["actor_revoked"]],
    ["ML-DSA request signature valid", ["bad_signature"]],
    ["Timestamp within ±30 s", ["stale_or_future_request"]],
    ["Nonce never seen before", ["replayed_request"]],
    ["Key version accepted", ["unknown_key_version", "key_version_retired"]],
  ];
  const out          = [];
  for (const [name, codes] of chain) {
    if (codes.includes(reason)) return [...out, { name, pass: false }];
    out.push({ name, pass: true });
  }
  return out;
}

const lastSeq = (paths            ) => {
  try {
    return readAudit(paths).at(-1)?.seq ?? null;
  } catch {
    return null;
  }
};

const decide = (r                         ) => (r.error ? `refused: ${String(r.error)}` : `${String(r.decision)}${r.body ? " (contents returned)" : ", no contents returned"}`);

function adapterStep(c     , req                         ) {
  const reply = c.call(req);
  let reason                = null;
  try {
    reason = readAudit(c.paths).filter((r) => r.request_id === req.request_id).at(-1)?.reason ?? null;
  } catch {
    reason = null;
  }
  return { reply, reason };
}

function loadLive(c     ) {
  const salt = Buffer.from((JSON.parse(JSON.parse(readFileSync(c.paths.state, "utf8")).body)                    ).salt, "base64");
  const master = loadMasterKey(c.paths);
  const keys = deriveKeys(master, salt);
  master.fill(0);
  return loadState(c.paths, keys.stateMac);
}

/** Which integrity check fails right now (the error message names the check, never data). */
function integrityReason(c     )         {
  try {
    loadLive(c);
    return "state verifies";
  } catch (err) {
    return err instanceof Error ? err.message : "integrity check failed";
  }
}

const healthy = (c     ) => {
  try {
    loadLive(c);
    return null;
  } catch {
    return "The service is fail-closed. Press Reset demo first.";
  }
};

// ---------- cluster helpers ----------

                                                                               
const device = (dir        ) => JSON.parse(readFileSync(join(dir, "demo-device.json"), "utf8"))              ;
const control = (dir        ) => ControlPlane.load(join(dir, "control"));
const nodeView = (dir        , name        ) => new ClusterNode(name, join(dir, name), control(dir).anchor, join(dir, "unused"));

function sendTo(dir        , name        , req                     , label        ) {
  const d = nodeView(dir, name).authorize(req);
  recordAttempt(dir, { at: Date.now(), device: req.device_id, node: name, decision: d.decision, reason: d.reason, label });
  return d;
}

function waitForEpoch(dir        , epoch        , limitMs = 3000)                {
  const start = Date.now();
  while (Date.now() - start < limitMs) {
    const all = NODE_NAMES.every((n) => {
      try {
        return (JSON.parse(readFileSync(join(dir, n, "ack.json"), "utf8"))                     ).epoch >= epoch;
      } catch {
        return false;
      }
    });
    if (all) return Date.now() - start;
    sleep(20);
  }
  return null;
}

const request = (dir        , d            , op                      = "request")                      =>
  signRequest(Buffer.from(d.privateKey, "base64"), { actor: "maya", device_id: d.device_id, key_version: control(dir).policy.active_key, op, transfer_id: null, nonce: randomBytes(8).toString("hex"), ts: Date.now() });

